const raw = String($input.first().json.text ?? '').trim();
const cleaned = raw
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    'Gagal parse JSON dari Basic LLM Chain: ' + error.message +
    '\n\nRaw output:\n' + raw
  );
}

const validCategories = [
  'Adventure', 'Agenda', 'Bengkel', 'CSR', 'Dealer', 'Formula 1',
  'Grasstrack', 'Internasional', 'Karting', 'Komunitas', 'Modifikasi',
  'Moto2', 'Moto3', 'MotoGP', 'Motocross', 'Motor Klasik', 'News',
  'Offroad', 'Produk', 'Profile', 'Rally', 'Road Race', 'Safety Riding',
  'Tips & Trik', 'WSBK'
];

const text = (value) => String(value ?? '').trim();
const category = validCategories.includes(text(parsed.category))
  ? text(parsed.category)
  : 'News';
const headline = text(parsed.headline).toUpperCase();
const subheadline = text(parsed.subheadline);
const caption = text(parsed.caption).replace(/\r\n/g, '\n');
const warnings = [];

if (category !== text(parsed.category)) warnings.push('Kategori AI tidak valid; diubah menjadi News.');
if (headline.split(/\s+/).filter(Boolean).length > 12) warnings.push('Headline melebihi 12 kata.');
if ([...headline].length > 80) warnings.push('Headline melebihi 80 karakter.');
if (subheadline.split(/\s+/).filter(Boolean).length > 20) warnings.push('Subheadline melebihi 20 kata.');
if (!caption.startsWith('Salam Otozoner!')) warnings.push('Pembuka caption tidak sesuai.');
if (!caption.includes('Baca ulasan lengkapnya di sini!\nKlik link di bio!')) warnings.push('CTA caption tidak sesuai.');
const hashtags = caption.match(/#[\p{L}\p{N}_]+/gu) || [];
if (hashtags.length > 5) warnings.push('Hashtag melebihi 5.');
if (hashtags[0] !== '#OtomotifZone') warnings.push('#OtomotifZone bukan hashtag pertama.');

return [{
  json: {
    category,
    confidence: Number.isFinite(Number(parsed.confidence)) ? Number(parsed.confidence) : 0,
    author: text(parsed.author) || 'Tim Redaksi',
    headline,
    subheadline,
    caption,
    source_link: text(parsed.source_link),
    image_url: text(parsed.image_url),
    validation_warnings: warnings
  }
}];

const item = $input.first().json;
let caption = item.caption || '';

caption = caption.replace(/
/g, '
');
caption = caption.replace(/Salam Otozoner!\s*/i, 'Salam Otozoner!

');
caption = caption.replace(/\s*Baca ulasan lengkapnya di sini!\s*/i, '

Baca ulasan lengkapnya di sini!
');
caption = caption.replace(/\s*Klik link di bio!\s*/i, '
Klik link di bio!

');
caption = caption.replace(/\s+(#OtomotifZone )/i, '

#OtomotifZone');
caption = caption.replace(/
{3,}/g, '

').trim();

const warnings = Array.isArray(item.validation_warnings)
  ? item.validation_warnings
  : [];
const warningBlock = warnings.length
  ? '

PERINGATAN:
- ' + warnings.join('
- ')
  : '';

const evidence = (item.verification_checks || []).slice(0, 6).map((c,i) => (i+1) + '. [' + c.result + '] ' + c.claim_type + ': ' + c.claim + '
   Bukti: “' + (c.source_quote || '-') + '”').join('
');
const verificationBlock = '

VERIFIKASI FAKTA: ' + (item.verification_status || 'WARNING') + '
' + (item.verification_summary || '-') + (evidence ? '
' + evidence : '');

const telegramCaption =
  'Kategori: ' + (item.category || '-') + '
' +
  'Confidence: ' + (item.confidence ?? 0) + '%' + '

' +
  'Penulis: ' + (item.author || '-') + '

' +
  'HEADLINE:
' + (item.headline || '-') + '

' +
  'SUBHEADLINE:
' + (item.subheadline || '-') + '

' +
  'CAPTION:
' + (caption || '-') +
  verificationBlock + warningBlock + '

' +
  'Source: ' + (item.source_link || '-');

return [{
  json: {
    ...item,
    caption,
    telegram_caption: telegramCaption,
    needs_review: warnings.length > 0
  }
}];

const item = $input.first().json;
const article = $('Limit').first().json;
const decode = (s) => String(s ?? '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;|&#160;/gi, ' ')
  .replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#0*39;|&apos;/gi, "'")
  .replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)));
const norm = (s) => decode(s).normalize('NFKC').replace(/\s+/g, ' ').trim();
const title = norm(article.title?.rendered || article.title || '');
const body = norm(article.content?.rendered || article.contentSnippet || '');
const source = norm(title + ' ' + body).slice(0, 60000);
const copy = norm([item.headline, item.subheadline, item.caption].join(' '));
const numberPattern = /\b\d+(?:[.,]\d+)*(?:\s?(?:%|cc|km|kg|hp|rpm|km\/j(?:am)?|detik|menit|jam|lap|race|seri))?\b/gi;
const unique = (xs) => [...new Set(xs.map(x => norm(x).toLowerCase()))];
const copyNumbers = unique(copy.match(numberPattern) || []);
const sourceLower = source.toLowerCase();
const missingNumbers = copyNumbers.filter(n => !sourceLower.includes(n));
return [{json:{...item, verification_source_text:source, verification_copy_text:copy,
  deterministic_number_tokens:copyNumbers, deterministic_missing_numbers:missingNumbers}}];

let raw=String($input.first().json.text??'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
let parsed; try { parsed=JSON.parse(raw); } catch(e) { throw new Error('JSON Fact Verifier tidak valid: '+e.message); }
const packet=$('Build Verification Packet').first().json;
const norm=(s)=>String(s??'').normalize('NFKC').replace(/\s+/g,' ').trim();
const source=norm(packet.verification_source_text).toLowerCase();
const allowed=new Set(['PASS','WARNING','FAIL']);
let status=allowed.has(String(parsed.status).toUpperCase())?String(parsed.status).toUpperCase():'WARNING';
const checks=(Array.isArray(parsed.checks)?parsed.checks:[]).slice(0,8).map((c)=>{
  const quote=norm(c.source_quote).slice(0,300);
  let result=allowed.has(String(c.result).toUpperCase())?String(c.result).toUpperCase():'WARNING';
  const exact=quote.length>=3 && source.includes(quote.toLowerCase());
  if(!exact) result='FAIL';
  return {claim_type:norm(c.claim_type).slice(0,40)||'lainnya',claim:norm(c.claim).slice(0,220),source_quote:quote,result,evidence_exact:exact};
});
const missing=Array.isArray(packet.deterministic_missing_numbers)?packet.deterministic_missing_numbers:[];
if(missing.length || checks.some(c=>c.result==='FAIL')) status='FAIL';
else if(!checks.length || checks.some(c=>c.result==='WARNING') || status==='WARNING') status='WARNING';
else status='PASS';
const summary=norm(parsed.summary).slice(0,300) || (status==='PASS'?'Semua klaim sensitif memiliki bukti sumber.':'Perlu pemeriksaan manusia.');
const warnings=[...(packet.validation_warnings||[])];
if(status!=='PASS') warnings.push('Fact Verifier '+status+': '+summary);
if(missing.length) warnings.push('Angka tidak ditemukan di sumber: '+missing.join(', '));
const out={...packet,verification_status:status,verification_summary:summary,verification_checks:checks,validation_warnings:warnings};
delete out.verification_source_text; delete out.verification_copy_text; delete out.deterministic_number_tokens; delete out.deterministic_missing_numbers;
return [{json:out}];
